// ── Closeout identity reconciliation（external REPAIR round 3）──────────
// The independent-review identity must be a PURE FUNCTION of the canonical
// evidence fields（recommendedAction + blockingFindings + graphRunId）, so the
// full-run bundle and EVERY regeneration of the same immutable evidence
// produce the SAME identity（self-consistent chain）. The original full-run
// identity included the complete review-agent result object（evidenceChecked /
// scopeVerified / testsVerified / …）which the evidence snapshot does NOT
// retain — it is therefore not reproducible from the canonical evidence and is
// replaced by the card-scoped, evidence-derived identity below. The graphRunId
// binding also guarantees the identity is COST-1's — never a stale CBM-3 /
// generic fallback value.
const cost1SourceBuilder = async ({ graphResult, closeout: co, evidence = [] }) => {
  const source = await buildGraphCloseoutSource({ graphResult, closeout: co, evidence });
  const gid = graphResult?.executionId ?? source.graph?.graphRunId ?? null;
  const reviewOutcomes = (graphResult?.nodeResults ?? [])
    .map((n) => n.reviewResult)
    .filter((r) => r && typeof r === "object" && !Array.isArray(r) && typeof r.recommendedAction === "string")
    .map((r) => ({ recommendedAction: r.recommendedAction, blockingFindings: Array.isArray(r.blockingFindings) ? r.blockingFindings.slice() : [] }));
  const reviewResultIdentity = sha256Hex(recursiveCanonicalJson({ graphRunId: gid, reviewOutcomes }));
  return {
    ...source,
    review: {
      ...(source.review ?? {}),
      reviewResultIdentity,
      summary: gid ? `independent review agent result (${gid})` : (source.review?.summary ?? "independent review agent result"),
    },
  };
};

