const REGENERATE = process.argv.includes("--regenerate");

if (REGENERATE) {
  const evidencePath = join(OUT, `${EXECUTION_ID}-graph-closeout-evidence.json`);
  const ev = JSON.parse(readFileSync(evidencePath, "utf8"));
  // Deterministic agent-execution-id reconstruction（canonical-evidence
  // derived）: agentExecutionId = agent_sha256(graphRunId:nodeId) per the
  // sub-agent contract; a node that went through a bounded repair carries the
  // stage-scoped repairer id（matches the original full-run envelope ids）.
  const repairedNodes = new Set(
    (ev.transitions ?? []).filter((t) => t.final === "REPAIR").map((t) => t.phaseId),
  );
  const graphResult = {
    executionId: ev.graphRunId,
    final: ev.final,
    holdCode: ev.holdCode ?? null,
    reason: ev.reason ?? null,
    scheduler: { ...(ev.scheduler ?? {}) },
    nodeResults: (ev.nodes ?? []).map((n) => ({
      nodeId: n.nodeId,
      phaseExecutionId: n.phaseExecutionId ?? null,
      taskType: n.taskType ?? null,
      dependencies: Array.isArray(n.dependencies) ? n.dependencies.slice() : [],
      final: n.final ?? null,
      attempt: n.attempt ?? null,
      reason: n.reason ?? null,
      startedAt: n.startedAt ?? null,
      completedAt: n.completedAt ?? null,
      cleanup: { worktreeRevoked: n.worktreeRevoked === true },
      worktreeIdentity: n.worktreeVerified === true ? { verified: true } : null,
      subagentEnvelope: {
        agentExecutionId: (repairedNodes.has(n.nodeId) || (n.attempt ?? 0) > 0)
          ? stageAgentExecutionId(ev.graphRunId, n.nodeId, "repairer")
          : agentExecutionIdFor(ev.graphRunId, n.nodeId),
      },
      subagentResult: n.subagentResultStatus
        ? { status: n.subagentResultStatus, testResults: n.subagentTestResults ?? null, testsExecuted: n.subagentTestResults ? ["regenerated from graph evidence"] : [] }
        : null,
      reviewResult: n.reviewResultStatus
        ? { recommendedAction: n.reviewResultStatus, blockingFindings: Array.isArray(n.reviewBlockingFindings) ? n.reviewBlockingFindings.slice() : [], summary: `independent review agent result (${ev.graphRunId})` }
        : null,
    })),
    transitions: (ev.transitions ?? []).map((t) => ({ ...t })),
  };
  const r = await runMandatoryGraphCloseout({
    graphResult,
    closeout: {
      ...closeout,
      // linear supersede chain: this generation supersedes the previously
      // delivered baa718e0 bundle（the one that received the external REPAIR
      // verdict）. Closeout-evidence reconciliation only — identity chain
      // rebuilt from canonical evidence; no source/regression change.
      supersedes: {
        reviewBundleIdentity: "baa718e09222ad6ae6558a05137ac89179c85b200172a7cc72fc8a51efe0a32d",
        reviewBundleSha256: "865a9fe91790add6b2aa5722d277b1934eed05df876b7467df8a6283db425607",
        bundlePath: join(OUT, "card-closeout-bundle-20260807-baa718e0.txt"),
        verdict: null,
        reviewedAt: null,
      },
    },
    repoPath: REPO_A,
    cwd: REPO_A,
    outDir: OUT,
    timeoutMs: 60000,
    sourceBuilder: cost1SourceBuilder,
  });
  console.log(`regenerate applied=${r.applied} final=${r.final} holdCode=${r.holdCode ?? "null"}`);
  if (r.bundlePath) {
    console.log(`bundle: ${r.bundlePath}`);
    console.log(`reviewBundleIdentity: ${r.bundle.identity}`);
    console.log(`reviewBundleSha256: ${r.bundle.sha256}`);
  }
  console.log(`externalReviewStatus: ${r.externalReview?.externalReviewStatus ?? "null"}`);
  console.log(`deliveryAttempted: ${r.externalReview?.delivery?.attempted ?? false}`);
  process.exit(r.final === "PASS" && r.externalReview?.externalReviewStatus === "AWAITING_EXTERNAL_REVIEW" ? 0 : 1);
}

const r = await runSubagentGraph({
  ir,
  parent: PARENT,
  cwd: REPO_A,
  executionId: EXECUTION_ID,
  profile: PROFILE,
  repoPath: REPO_A,
  scratchRoot: SCRATCH,
  maxRepairAttempts: 1,
  timeoutMs: 240000,
  memory: { provider: createGraphMemoryProvider({}) }, // dogfood: EMPTY_MEMORY or AVAILABLE; never writes
  telemetry, // COST-1 dogfooding: the graph itself is telemetry-observed
  closeoutSourceBuilder: cost1SourceBuilder, // identity chain self-consistency
  closeout,
});

console.log(`graph final=${r.final} reason=${r.reason ?? "null"}`);
console.log(`memoryContext state=${r.memoryContext?.state ?? "null"}`);
console.log(`telemetry observed=${r.telemetry?.observed ?? false} events=${r.telemetry?.events ?? 0} holdCode=${r.telemetry?.holdCode ?? "null"}`);
console.log(`closeout applied=${r.closeout.applied} final=${r.closeout.final} holdCode=${r.closeout.holdCode ?? "null"}`);
if (r.closeout.reason) console.log(`closeout reason: ${r.closeout.reason}`);
if (r.closeout.bundlePath) {
  console.log(`bundle: ${r.closeout.bundlePath}`);
  console.log(`reviewBundleIdentity: ${r.closeout.bundle.identity}`);
  console.log(`reviewBundleSha256: ${r.closeout.bundle.sha256}`);
}
if (r.closeout.externalReview) {
  console.log(`externalReviewStatus: ${r.closeout.externalReview.externalReviewStatus}`);
  console.log(`deliveryAttempted: ${r.closeout.externalReview.delivery?.attempted ?? false}`);
}
const w1 = r.nodeResults.find((n) => n.nodeId === "SA-W1");
if (w1) console.log(`W1 attempt=${w1.attempt} review=${w1.reviewResult?.recommendedAction} blocking=${JSON.stringify(w1.reviewResult?.blockingFindings ?? [])}`);

try { telemetryStore.close(); } catch { /* best effort */ }
rmSync(SCRATCH, { recursive: true, force: true });
process.exit(r.final === "PASS" && r.closeout.final === "PASS" ? 0 : 1);
